package dev.izzy.factorycore.platform.client.ui;

import dev.izzy.factorycore.platform.FactoryCoreMod;
import net.minecraft.client.gui.Font;
import net.minecraft.client.gui.GuiGraphics;
import net.minecraft.network.chat.Component;
import net.minecraft.resources.ResourceLocation;

/**
 * Draws the panel kit (ADR 0064): the panel, sunken insets and slots, the title and wrapped body
 * text. Sprites are generated by {@code tools/art/generate_art.py} and nine-sliced by their {@code
 * .mcmeta}. Colors are for the light panel face; text never relies on color alone.
 */
public final class Panels {
  public static final ResourceLocation PANEL = sprite("panel"),
      INSET = sprite("inset"),
      SLOT = sprite("slot"),
      CHOICE_SELECTED = sprite("choice_selected"),
      CHECKBOX = sprite("checkbox"),
      CHECKBOX_CHECKED = sprite("checkbox_checked");

  /** Text on the panel face: normal, secondary, good, warning and error. */
  public static final int TEXT = 0x404040,
      MUTED = 0x6b6b6b,
      GOOD = 0x1e6b24,
      WARN = 0x8a5200,
      BAD = 0xa01e1e;

  private Panels() {}

  private static ResourceLocation sprite(String name) {
    return ResourceLocation.fromNamespaceAndPath(FactoryCoreMod.MOD_ID, name);
  }

  /** The panel background for {@code layout} at absolute {@code left, top}. */
  public static void panel(GuiGraphics graphics, int left, int top, PanelLayout layout) {
    graphics.blitSprite(PANEL, left, top, layout.width(), layout.height());
  }

  /** A sunken area for lists, text and grids. */
  public static void inset(GuiGraphics graphics, Rect area) {
    graphics.blitSprite(INSET, area.x(), area.y(), area.width(), area.height());
  }

  /** One 18×18 item slot whose item sits at {@code x + 1, y + 1}. */
  public static void slot(GuiGraphics graphics, int x, int y) {
    graphics.blitSprite(SLOT, x, y, PanelLayout.SLOT, PanelLayout.SLOT);
  }

  /** The title at the vanilla position; {@code left, top} is the panel's corner. */
  public static void title(GuiGraphics graphics, Font font, Component title, int left, int top) {
    graphics.drawString(
        font, title, left + PanelLayout.EDGE + 1, top + PanelLayout.TITLE_Y, TEXT, false);
  }

  /**
   * Draws {@code text} wrapped to {@code area}, one {@link PanelLayout#LINE} per line, stopping at
   * the last line that fits. Returns the number of lines drawn.
   */
  public static int wrapped(GuiGraphics graphics, Font font, Component text, Rect area, int color) {
    int lines = 0;
    for (var line : font.split(text, area.width())) {
      int y = area.y() + lines * PanelLayout.LINE;
      if (y + font.lineHeight > area.bottom()) break;
      graphics.drawString(font, line, area.x(), y, color, false);
      lines++;
    }
    return lines;
  }
}
